begin;

create schema if not exists pani_private;

create table if not exists pani_private.eco_seed_library(
  seed_id integer primary key check(seed_id between 1 and 10),
  gen_phase1 text[] not null,
  gen_main text[] not null,
  sec_route text[] not null
);

insert into pani_private.eco_seed_library values
 (1,array['A1','C3','NØ'],array['B2','D4','A1','NØ'],array['HUB','SEC','OPS','MED','INV','GEN']),
 (2,array['B2','NØ','D4'],array['C3','A1','NØ','B2'],array['OPS','HUB','SEC','GEN','INV','MED']),
 (3,array['D4','A1','C3'],array['NØ','B2','D4','A1'],array['MED','HUB','OPS','SEC','GEN','INV']),
 (4,array['NØ','D4','B2'],array['A1','C3','B2','NØ'],array['GEN','SEC','HUB','OPS','MED','INV']),
 (5,array['C3','B2','A1'],array['D4','NØ','C3','B2'],array['INV','MED','HUB','SEC','OPS','GEN']),
 (6,array['A1','NØ','D4'],array['C3','D4','B2','A1'],array['SEC','HUB','MED','OPS','INV','GEN']),
 (7,array['D4','C3','NØ'],array['B2','A1','NØ','D4'],array['OPS','SEC','HUB','INV','MED','GEN']),
 (8,array['B2','A1','C3'],array['NØ','D4','A1','C3'],array['GEN','HUB','SEC','OPS','INV','MED']),
 (9,array['NØ','C3','A1'],array['D4','B2','C3','NØ'],array['MED','OPS','HUB','SEC','INV','GEN']),
 (10,array['C3','D4','B2'],array['A1','NØ','D4','C3'],array['INV','HUB','OPS','SEC','GEN','MED'])
on conflict(seed_id) do update set gen_phase1=excluded.gen_phase1,gen_main=excluded.gen_main,sec_route=excluded.sec_route;

create table if not exists pani_private.eco_session(
  session_id text primary key,
  released boolean not null default false,
  status text not null default 'dormant' check(status in ('dormant','active','convergence','complete')),
  paused boolean not null default false,
  paused_at timestamptz,
  seed_id integer not null default 1 references pani_private.eco_seed_library(seed_id),
  global_pressure integer not null default 0 check(global_pressure>=0),
  presence_charges integer not null default 5 check(presence_charges between 0 and 5),
  rupture_available boolean not null default true,
  coherence integer not null default 12 check(coherence between 0 and 100),
  convergence jsonb not null default '{}'::jsonb,
  secret_state jsonb not null default '{}'::jsonb,
  revision bigint not null default 0,
  updated_at timestamptz not null default now()
);

create table if not exists pani_private.eco_anchor(
  session_id text not null references pani_private.eco_session(session_id) on delete cascade,
  crew_id text not null references public.crew_access(crew_id),
  anchor_id text not null,
  phase integer not null default 1 check(phase between 1 and 4),
  stability integer not null default 3 check(stability between 0 and 3),
  progress integer not null default 0 check(progress between 0 and 100),
  public_state jsonb not null default '{}'::jsonb,
  secret_state jsonb not null default '{}'::jsonb,
  public_log jsonb not null default '[]'::jsonb,
  help_tokens integer not null default 0 check(help_tokens>=0),
  locked boolean not null default false,
  joined boolean not null default false,
  joined_at timestamptz,
  last_seen timestamptz,
  interference jsonb not null default '{}'::jsonb,
  revision bigint not null default 0,
  updated_at timestamptz not null default now(),
  primary key(session_id,crew_id),unique(session_id,anchor_id)
);

create table if not exists pani_private.eco_log(
  id bigint generated by default as identity primary key,
  session_id text not null,
  actor text not null,event_type text not null,detail text,
  payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

alter table pani_private.eco_seed_library enable row level security;
alter table pani_private.eco_session enable row level security;
alter table pani_private.eco_anchor enable row level security;
alter table pani_private.eco_log enable row level security;
revoke all on table pani_private.eco_seed_library,pani_private.eco_session,pani_private.eco_anchor,pani_private.eco_log from public,anon,authenticated;
revoke all on sequence pani_private.eco_log_id_seq from public,anon,authenticated;

insert into pani_private.eco_session(session_id) values('W77-02') on conflict do nothing;

create or replace function pani_private.eco_active_crew() returns text[] language sql immutable set search_path=pg_catalog
as $$select array['gilbert','eklay','christian','willy','aliya']::text[]$$;

create or replace function pani_private.eco_anchor_name(p text) returns text language sql immutable set search_path=pg_catalog
as $$select case p when 'gilbert' then 'gen' when 'eklay' then 'ops' when 'christian' then 'sec' when 'willy' then 'med' when 'aliya' then 'inv' end$$;

create or replace function pani_private.eco_auth_crew(p_token text) returns text language plpgsql security definer
set search_path=pg_catalog,public,extensions as $$declare c text;begin
 select crew_id into c from public.crew_access where token_hash=encode(extensions.digest(coalesce(p_token,''),'sha256'),'hex');
 if c is null then raise exception 'unauthorized';end if;return c;end$$;

create or replace function pani_private.eco_edge(a text,b text) returns text language sql immutable set search_path=pg_catalog as $$
select case when a||':'||b in ('HUB:SEC','SEC:HUB','OPS:HUB','HUB:OPS','MED:HUB','HUB:MED','GEN:SEC','SEC:GEN') then 'PORTA'
 when a||':'||b in ('SEC:OPS','OPS:SEC','MED:INV','INV:MED','GEN:INV','INV:GEN') then 'DUTO'
 when a||':'||b in ('OPS:MED','MED:OPS','SEC:INV','INV:SEC','HUB:GEN','GEN:HUB') then 'SERVIÇO' end$$;

create or replace function pani_private.eco_phase_public(c text,p integer,s integer) returns jsonb language plpgsql set search_path=pg_catalog,pani_private as $$
begin
 if c='gilbert' then return case p
  when 1 then '{"title":"LINHA DE BASE","slots":3,"values":["A1","B2","C3","D4","NØ"],"maxAttempts":6,"history":[],"feedback":"Selecione três marcadores e teste a assinatura."}'::jsonb
  when 2 then '{"title":"ÂNCORA FILOGENÉTICA","slots":4,"values":["A1","B2","C3","D4","NØ"],"maxAttempts":8,"history":[],"verifiers":["ORIGEM","COMPATIBILIDADE","CONTENÇÃO"],"feedback":"Compare código e verificadores."}'::jsonb
  when 3 then '{"title":"DIVERGÊNCIA NØ","slots":4,"values":["A1","B2","C3","D4","NØ"],"history":[],"tests":0,"verifiers":["ORIGEM","COMPATIBILIDADE","CONTENÇÃO","DESCRIÇÃO"],"feedback":"Produza três leituras e identifique o verificador incompatível."}'::jsonb
  else '{"title":"FIXAÇÃO DA ASSINATURA","slots":4,"values":["A1","B2","C3","D4","NØ"],"feedback":"Separe suporte físico e descrição antes de fixar a verdade."}'::jsonb end;
 elsif c='eklay' then return case p
  when 1 then '{"title":"ROTA FRIA","gridSize":5,"origin":"0,0","destination":"4,4","queue":["straight","elbow","straight","elbow","straight","elbow","straight","elbow"],"placed":{},"queueIndex":0,"anchors":[],"pathLength":8,"feedback":"Construa uma rota de oito peças. Sem limite de tempo."}'::jsonb
  when 2 then '{"title":"PULSO AO VIVO","gridSize":6,"origin":"0,0","destination":"5,5","queue":["straight","elbow","straight","elbow","straight","straight","elbow","straight","elbow","straight"],"placed":{},"queueIndex":0,"anchors":[],"pathLength":10,"buildDeadline":null,"flowStartedAt":null,"flowCompleteAt":null,"pulseIndex":0,"feedback":"O pulso inicia 12 segundos após a primeira peça."}'::jsonb
  when 3 then '{"title":"PARALAXE NULA","gridSize":6,"origin":"0,5","destination":"5,0","apparentDestination":"5,5","queue":["straight","elbow","straight","bridge","straight","elbow","straight","elbow","straight"],"placed":{},"queueIndex":0,"anchors":[],"pathLength":9,"buildDeadline":null,"flowStartedAt":null,"flowCompleteAt":null,"pulseIndex":0,"targetShifted":false,"feedback":"A PONTE DE REFERÊNCIA conecta bordas opostas."}'::jsonb
  else '{"title":"LOCK R-3","nodes":["A","B","C"],"nodeIndex":0,"feedback":"Estabilize NODE A, B e C na ordem indicada."}'::jsonb end;
 elsif c='christian' then return case p
  when 1 then '{"title":"CALIBRAÇÃO IFF-Ø","graph":["HUB","SEC","OPS","MED","INV","GEN"],"round":0,"findings":0,"moveLog":[],"feedback":"Contato de treinamento ativo. Use SCAN para calibrar."}'::jsonb
  when 2 then '{"title":"MOVIMENTO OCULTO","graph":["HUB","SEC","OPS","MED","INV","GEN"],"routeIndex":0,"findings":0,"moveLog":[],"scanLog":[],"lockdowns":2,"camera":1,"feedback":"O contato avança após cada ação. O destino não é revelado."}'::jsonb
  when 3 then '{"title":"PERÍMETRO INVALIDADO","graph":["HUB","SEC","OPS","MED","INV","GEN"],"routeIndex":0,"moveLog":[],"scanLog":[],"jumpObserved":false,"feedback":"Encontre o ponto em que a cadeia de adjacência foi quebrada."}'::jsonb
  else '{"title":"BLACKBOX","timeline":["PORTA","DUTO","?","SERVIÇO","PORTA"],"appearances":[1,4],"closedDoors":["HUB","SEC","OPS","GEN"],"selected":null,"feedback":"Marque o primeiro ponto impossível da trilha."}'::jsonb end;
 elsif c='willy' then return case p
  when 1 then '{"title":"LINHA DE BASE","channels":["pulse","resp","neural","tonus"],"sequence":["pulse","resp","neural","tonus"],"length":4,"feedback":"Observe e repita os quatro canais."}'::jsonb
  when 2 then '{"title":"DEFASAGEM","channels":["pulse","resp","neural","tonus"],"sequence":[{"channel":"pulse","time":0},{"channel":"resp","time":720},{"channel":"neural","time":1390},{"channel":"tonus","time":2050},{"channel":"pulse","time":2720}],"round":0,"feedback":"Repita a ordem e o ritmo. Janela aceita: ±450 ms."}'::jsonb
  when 3 then '{"title":"EVENTO COLETIVO 03:17","tracks":["T01","T02","T03","T04","T05","T06"],"visualStarts":[31,34,29,33,30,35],"environmentEnd":40,"markers":[],"feedback":"Marque o início dos seis traços e determine a relação temporal."}'::jsonb
  else '{"title":"FIXAÇÃO SOMÁTICA","channels":["pulse","resp","neural","tonus"],"displaySequence":["pulse","resp","neural","pani","tonus","pulse"],"feedback":"Ignore o pulso PANI inexistente e preserve somente o registro bruto."}'::jsonb end;
 elsif c='aliya' then return case p
  when 1 then '{"title":"CLASSIFICAR SEM INTERPRETAR","cards":[{"id":"A1","text":"Amostra preserva massa e suporte físico."},{"id":"A2","text":"Descrição biológica diverge após nova leitura."},{"id":"B1","text":"Pulso cruza o limite sem trajetória completa."},{"id":"B2","text":"Destino R-3 não possui posição convencional."},{"id":"C1","text":"Portas de fronteira permanecem fechadas."},{"id":"C2","text":"Presença confirmada no interior do setor."},{"id":"D1","text":"Evento ambiental registrado em T+0."},{"id":"D2","text":"Resposta corporal começa em T-0,6."},{"id":"E1","text":"Cinco timestamps apontam a mesma janela."},{"id":"E2","text":"Suportes diferentes repetem a mesma relação."}],"operations":["LOCALIZAR","DEFINIR","PERCEBER","DELIMITAR","RELACIONAR"],"assignments":{},"feedback":"Distribua dois cartões em cada operação."}'::jsonb
  when 2 then '{"title":"CONTRADIÇÕES VÁLIDAS","statements":[{"id":"SEC-A","text":"Porta SEC nunca abriu"},{"id":"SEC-B","text":"Presença registrada dentro do setor"},{"id":"GEN-A","text":"Amostra física não mudou"},{"id":"GEN-B","text":"Descrição genética mudou"},{"id":"MED-A","text":"Evento ambiental inicia em T+0"},{"id":"MED-B","text":"Corpos reagem em T-0,6"},{"id":"OPS-A","text":"Rota termina no destino"},{"id":"OPS-B","text":"Destino não possui posição convencional"}],"pairs":[],"feedback":"Conecte quatro pares incompatíveis sob uma explicação convencional."}'::jsonb
  when 3 then '{"title":"UMA OCORRÊNCIA OU CINCO?","hypotheses":[{"id":"five","title":"5 FALHAS INDEPENDENTES","prediction":"Deveriam ocorrer sem correlação temporal."},{"id":"pani","title":"PANI DANIFICADA","prediction":"Deveria afetar apenas registros digitais."},{"id":"one","title":"1 FENÔMENO / 5 SUPORTES","prediction":"Pode aparecer em tecnologia, corpo, matéria, segurança e relações."}],"tested":{},"feedback":"Teste previsões e descarte explicações que não sobrevivem às evidências."}'::jsonb
  else '{"title":"FIXAR A RELAÇÃO","outputs":["GEN","OPS","SEC","MED","INV"],"linked":[],"feedback":"Una os cinco resultados sem atribuir nome ou semântica."}'::jsonb end;
 end if;return '{}'::jsonb;
end$$;

create or replace function pani_private.eco_phase_secret(c text,p integer,s integer) returns jsonb language plpgsql set search_path=pg_catalog,pani_private as $$
declare z pani_private.eco_seed_library%rowtype;begin select * into z from pani_private.eco_seed_library where seed_id=s;
 if c='gilbert' then return jsonb_build_object('code',to_jsonb(case when p=1 then z.gen_phase1 else z.gen_main end),'correctSuspect','DESCRIÇÃO');
 elsif c='eklay' then return case p
  when 1 then '{"solution":[{"cell":"0,1","piece":"straight","rot":0},{"cell":"0,2","piece":"elbow","rot":1},{"cell":"1,2","piece":"straight","rot":1},{"cell":"2,2","piece":"elbow","rot":2},{"cell":"2,3","piece":"straight","rot":0},{"cell":"2,4","piece":"elbow","rot":2},{"cell":"3,4","piece":"straight","rot":1},{"cell":"4,4","piece":"elbow","rot":3}]}'::jsonb
  when 2 then '{"solution":[{"cell":"0,1","piece":"straight","rot":0},{"cell":"0,2","piece":"elbow","rot":1},{"cell":"1,2","piece":"straight","rot":1},{"cell":"2,2","piece":"elbow","rot":2},{"cell":"2,3","piece":"straight","rot":0},{"cell":"2,4","piece":"straight","rot":0},{"cell":"2,5","piece":"elbow","rot":2},{"cell":"3,5","piece":"straight","rot":1},{"cell":"4,5","piece":"elbow","rot":3},{"cell":"5,5","piece":"straight","rot":1}]}'::jsonb
  when 3 then '{"solution":[{"cell":"0,4","piece":"straight","rot":0},{"cell":"0,3","piece":"elbow","rot":1},{"cell":"1,3","piece":"straight","rot":1},{"cell":"2,3","piece":"bridge","rot":0},{"cell":"3,2","piece":"straight","rot":1},{"cell":"4,2","piece":"elbow","rot":2},{"cell":"4,1","piece":"straight","rot":0},{"cell":"4,0","piece":"elbow","rot":1},{"cell":"5,0","piece":"straight","rot":1}]}'::jsonb
  else '{"nodes":["A","B","C"]}'::jsonb end;
 elsif c='christian' then return case p when 1 then '{"route":["SEC","OPS","HUB"],"routeIndex":0,"current":"SEC"}'::jsonb when 2 then jsonb_build_object('route',to_jsonb(z.sec_route),'routeIndex',0) when 3 then jsonb_build_object('route',to_jsonb(z.sec_route),'routeIndex',0,'jumpIndex',2) else '{"firstImpossible":2}'::jsonb end;
 elsif c='willy' then return case p when 1 then '{"fullSequence":["pulse","resp","neural","tonus","pulse","neural","resp"]}'::jsonb when 2 then '{"sequence":[{"channel":"pulse","time":0},{"channel":"resp","time":720},{"channel":"neural","time":1390},{"channel":"tonus","time":2050},{"channel":"pulse","time":2720}],"rounds":2}'::jsonb when 3 then '{"starts":[31,34,29,33,30,35],"conclusion":"anticipated"}'::jsonb else '{"rawSequence":["pulse","resp","neural","tonus","pulse"]}'::jsonb end;
 elsif c='aliya' then return case p when 1 then '{"assignments":{"A1":"DEFINIR","A2":"DEFINIR","B1":"LOCALIZAR","B2":"LOCALIZAR","C1":"DELIMITAR","C2":"DELIMITAR","D1":"PERCEBER","D2":"PERCEBER","E1":"RELACIONAR","E2":"RELACIONAR"}}'::jsonb when 2 then '{"pairs":[["SEC-A","SEC-B"],["GEN-A","GEN-B"],["MED-A","MED-B"],["OPS-A","OPS-B"]]}'::jsonb when 3 then '{"results":{"five":"FAIL","pani":"FAIL","one":"PASS"}}'::jsonb else '{"outputs":["GEN","OPS","SEC","MED","INV"],"noName":true}'::jsonb end;end if;return '{}'::jsonb;
end$$;

create or replace function pani_private.eco_log_write(a text,e text,d text default null,x jsonb default '{}'::jsonb) returns void language sql set search_path=pg_catalog,pani_private as $$insert into pani_private.eco_log(session_id,actor,event_type,detail,payload) values('W77-02',left(coalesce(a,'SYSTEM'),80),left(coalesce(e,'event'),80),left(coalesce(d,''),500),coalesce(x,'{}'))$$;

create or replace function pani_private.eco_reset(s integer default 1,r boolean default true) returns void language plpgsql set search_path=pg_catalog,pani_private as $$declare c text;begin
 if s not between 1 and 10 then raise exception 'invalid_seed';end if;
 insert into pani_private.eco_session(session_id) values('W77-02') on conflict do nothing;
 update pani_private.eco_session set released=r,status=case when r then 'active' else 'dormant' end,paused=false,paused_at=null,seed_id=s,global_pressure=0,presence_charges=5,rupture_available=true,coherence=12,convergence='{}',secret_state=jsonb_build_object('secRoute',(select to_jsonb(sec_route) from pani_private.eco_seed_library where seed_id=s)),revision=revision+1,updated_at=now() where session_id='W77-02';
 delete from pani_private.eco_anchor where session_id='W77-02';
 foreach c in array pani_private.eco_active_crew() loop insert into pani_private.eco_anchor(session_id,crew_id,anchor_id,public_state,secret_state) values('W77-02',c,pani_private.eco_anchor_name(c),pani_private.eco_phase_public(c,1,s),pani_private.eco_phase_secret(c,1,s));end loop;
 perform pani_private.eco_log_write('MASTER',case when r then 'protocol_started' else 'protocol_reset' end,'ECO-W77 // CINCO ÂNCORAS',jsonb_build_object('seed',s));
end$$;

create or replace function pani_private.eco_fail(c text,reason text) returns void language plpgsql set search_path=pg_catalog,pani_private as $$declare a pani_private.eco_anchor%rowtype;s int;begin
 select * into a from pani_private.eco_anchor where session_id='W77-02' and crew_id=c for update;select seed_id into s from pani_private.eco_session where session_id='W77-02';
 if a.stability>1 then update pani_private.eco_anchor set stability=stability-1,public_state=public_state||jsonb_build_object('feedback',left(reason,240),'serverAck','REGISTRADO // ESTABILIDADE REDUZIDA'),public_log=public_log||jsonb_build_array(jsonb_build_object('at',now(),'type','error','text',left(reason,240))),revision=revision+1,updated_at=now() where session_id='W77-02' and crew_id=c;
 else update pani_private.eco_anchor set stability=3,help_tokens=help_tokens+1,public_state=pani_private.eco_phase_public(c,a.phase,s)||'{"advantage":true,"feedback":"Fase recalibrada. AJUDA PANI compensatória concedida.","serverAck":"RECALIBRAÇÃO REGISTRADA"}'::jsonb,secret_state=pani_private.eco_phase_secret(c,a.phase,s),public_log=public_log||jsonb_build_array(jsonb_build_object('at',now(),'type','recalibration','text','Fase recalibrada sem apagar fases anteriores.')),revision=revision+1,updated_at=now() where session_id='W77-02' and crew_id=c;update pani_private.eco_session set global_pressure=global_pressure+1,revision=revision+1 where session_id='W77-02';end if;
 perform pani_private.eco_log_write(c,'anchor_error',reason,jsonb_build_object('phase',a.phase));
end$$;

create or replace function pani_private.eco_advance(c text,outp text default null) returns void language plpgsql set search_path=pg_catalog,pani_private as $$declare a pani_private.eco_anchor%rowtype;s int;n int;begin
 select * into a from pani_private.eco_anchor where session_id='W77-02' and crew_id=c for update;select seed_id into s from pani_private.eco_session where session_id='W77-02';
 if a.phase=4 then update pani_private.eco_anchor set locked=true,progress=100,stability=3,public_state=public_state||jsonb_build_object('output',coalesce(outp,'ÂNCORA FIXADA'),'feedback','ÂNCORA FIXADA // AGUARDANDO CONVERGÊNCIA','serverAck','LOCK REGISTRADO'),revision=revision+1,updated_at=now() where session_id='W77-02' and crew_id=c;perform pani_private.eco_log_write(c,'anchor_locked',coalesce(outp,'ÂNCORA FIXADA'));
 else n:=a.phase+1;update pani_private.eco_anchor set phase=n,progress=(n-1)*25,stability=3,public_state=pani_private.eco_phase_public(c,n,s)||'{"serverAck":"FASE REGISTRADA"}'::jsonb,secret_state=pani_private.eco_phase_secret(c,n,s),public_log=public_log||jsonb_build_array(jsonb_build_object('at',now(),'type','phase','text','FASE '||a.phase||' CONCLUÍDA')),revision=revision+1,updated_at=now() where session_id='W77-02' and crew_id=c;
 if c='christian' and n in(2,3) then update pani_private.eco_anchor set secret_state=jsonb_set(secret_state,'{route}',(select secret_state->'secRoute' from pani_private.eco_session where session_id='W77-02')) where session_id='W77-02' and crew_id=c;end if;perform pani_private.eco_log_write(c,'phase_advanced','FASE '||n);end if;
end$$;

create or replace function pani_private.eco_same(a jsonb,b jsonb) returns boolean language sql immutable set search_path=pg_catalog as $$select jsonb_typeof(a)='array' and a=b$$;
create or replace function pani_private.eco_ops_valid(a jsonb,b jsonb) returns boolean language sql immutable set search_path=pg_catalog as $$select jsonb_typeof(a)='object' and not exists(select 1 from jsonb_array_elements(b) s where not(a?(s->>'cell')) or a#>>array[s->>'cell','piece']<>s->>'piece' or coalesce((a#>>array[s->>'cell','rot'])::int,-1)<>(s->>'rot')::int)$$;
create or replace function pani_private.eco_code_feedback(g jsonb,c jsonb) returns jsonb language plpgsql set search_path=pg_catalog as $$declare e int;p int;begin if jsonb_typeof(g)<>'array' or jsonb_array_length(g)<>jsonb_array_length(c) then raise exception 'invalid_guess';end if;select count(*) into e from generate_series(0,jsonb_array_length(c)-1)i where g->>i=c->>i;select coalesce(sum(least(x.n,y.n)),0)-e into p from(select value,count(*)n from jsonb_array_elements_text(g)group by value)x join(select value,count(*)n from jsonb_array_elements_text(c)group by value)y using(value);return jsonb_build_object('exact',e,'present',greatest(p,0));end$$;

create or replace function pani_private.eco_hint(c text,p int) returns text language sql immutable set search_path=pg_catalog as $$select case c when 'gilbert' then 'Compare EXATOS e PRESENTES; descrição e suporte são camadas diferentes.' when 'eklay' then 'A fila é determinística; SEGURAR protege uma peça.' when 'christian' then 'O tipo do deslocamento reduz as arestas possíveis.' when 'willy' then 'A ordem vale tanto quanto o intervalo; som é opcional.' when 'aliya' then 'Fixe a relação sem atribuir nome ou autoria.' end$$;

create or replace function pani_private.eco_tick_session() returns void language plpgsql set search_path=pg_catalog,pani_private as $$declare s pani_private.eco_session%rowtype;l int;r int;st text;t timestamptz;a int;begin
 select * into s from pani_private.eco_session where session_id='W77-02' for update;if not s.released or s.paused then return;end if;select count(*) into l from pani_private.eco_anchor where session_id='W77-02' and locked;
 if s.status='active' and l=5 then update pani_private.eco_session set status='convergence',convergence=jsonb_build_object('state','open','ready','[]'::jsonb,'readyCount',0,'attempt',1,'windowOpenedAt',now(),'windowEnd',now()+interval '12 seconds','retryAt',null),revision=revision+1,updated_at=now() where session_id='W77-02';perform pani_private.eco_log_write('SYSTEM','convergence_open','JANELA 5/5 ABERTA');return;end if;
 if s.status<>'convergence' then return;end if;st:=s.convergence->>'state';if st='open' and now()>(s.convergence->>'windowEnd')::timestamptz then r:=coalesce((s.convergence->>'readyCount')::int,0);if r<5 then update pani_private.eco_session set convergence=convergence||jsonb_build_object('state','recalibrating','ready','[]'::jsonb,'readyCount',0,'windowEnd',null,'retryAt',now()+interval '20 seconds'),revision=revision+1 where session_id='W77-02';end if;
 elsif st='recalibrating' and now()>=(s.convergence->>'retryAt')::timestamptz then a:=coalesce((s.convergence->>'attempt')::int,1)+1;update pani_private.eco_session set convergence=jsonb_build_object('state','open','ready','[]'::jsonb,'readyCount',0,'attempt',a,'windowOpenedAt',now(),'windowEnd',now()+interval '12 seconds','retryAt',null),revision=revision+1 where session_id='W77-02';end if;
end$$;

create or replace function pani_private.eco_tick_anchor(c text) returns void language plpgsql set search_path=pg_catalog,pani_private as $$declare a pani_private.eco_anchor%rowtype;s pani_private.eco_session%rowtype;st timestamptz;fin timestamptz;i int;begin
 select * into s from pani_private.eco_session where session_id='W77-02';if s.paused then return;end if;select * into a from pani_private.eco_anchor where session_id='W77-02' and crew_id=c for update;if c<>'eklay' or a.phase not in(2,3) then return;end if;
 if coalesce((a.public_state->>'routeValid')::boolean,false) and nullif(a.public_state->>'flowStartedAt','') is not null then st:=(a.public_state->>'flowStartedAt')::timestamptz;fin:=(a.public_state->>'flowCompleteAt')::timestamptz;i:=greatest(0,least((a.public_state->>'pathLength')::int,floor(extract(epoch from(now()-st))/1.3)::int));update pani_private.eco_anchor set public_state=jsonb_set(public_state,'{pulseIndex}',to_jsonb(i)),revision=revision+1 where session_id='W77-02' and crew_id=c;if now()>=fin then perform pani_private.eco_advance(c);end if;
 elsif nullif(a.public_state->>'buildDeadline','') is not null and now()>=(a.public_state->>'buildDeadline')::timestamptz then perform pani_private.eco_fail(c,'PONTA MORTA // O pulso alcançou uma peça incompatível.');end if;
end$$;

create or replace function public.pani_eco_status(p_token text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pani_private,extensions as $$declare c text;s pani_private.eco_session%rowtype;a pani_private.eco_anchor%rowtype;o int;l int;co int;cl text;outp text;inter jsonb;begin
 c:=pani_private.eco_auth_crew(p_token);select * into s from pani_private.eco_session where session_id='W77-02';if not(c=any(pani_private.eco_active_crew())) then return jsonb_build_object('eligible',false,'released',s.released,'status',s.status,'reason','Esta credencial não integra as cinco âncoras atuais.');end if;
 if s.released then update pani_private.eco_anchor set joined=true,joined_at=coalesce(joined_at,now()),last_seen=now() where session_id='W77-02' and crew_id=c;select count(*) into o from pani_private.eco_anchor where session_id='W77-02' and joined and last_seen>now()-interval '35 seconds';co:=case when o>=5 then 100 when o=4 then 42 else least(35,12+o*5) end;update pani_private.eco_session set coherence=co,revision=revision+1,updated_at=now() where session_id='W77-02' and coherence is distinct from co;end if;
 perform pani_private.eco_tick_anchor(c);perform pani_private.eco_tick_session();select * into s from pani_private.eco_session where session_id='W77-02';select * into a from pani_private.eco_anchor where session_id='W77-02' and crew_id=c;select count(*) into l from pani_private.eco_anchor where session_id='W77-02' and locked;
 cl:=case c when 'gilbert' then 'NODE R3-7' when 'eklay' then 'IFF Ø-C' when 'christian' then 'DELTA -0,6' when 'willy' then 'NØ' when 'aliya' then '03:16:59 // 03:17:00 // 03:16:59.4 // 03:17:00 // 03:16:59.7' end;outp:=case c when 'gilbert' then 'SUPORTE PRESERVADO // DESCRIÇÃO INCONSISTENTE // TIMESTAMP ECO GERADO.' when 'eklay' then 'ROTA VALIDADA // DESTINO SEM POSIÇÃO CONVENCIONAL.' when 'christian' then 'PRESENÇA INTERNA CONFIRMADA // CADEIA INCOMPLETA.' when 'willy' then 'RESPOSTA COLETIVA // ANTECEDE REGISTRO AMBIENTAL.' when 'aliya' then 'CINCO SUPORTES // UMA ESTRUTURA RECORRENTE // SEM NOME.' end;inter:=case when nullif(a.interference->>'until','') is not null and(a.interference->>'until')::timestamptz>now() then a.interference else '{}' end;
 return jsonb_build_object('eligible',true,'released',s.released,'status',s.status,'paused',s.paused,'coherence',s.coherence,'globalPressure',s.global_pressure,'locks',l,'presenceRemaining',s.presence_charges,'convergence',case when s.status in('convergence','complete')then s.convergence else '{}' end,'sixthLayer',case when s.status='complete' then jsonb_build_object('historicalLayers',6,'activeAnchors',5,'layer','ENV','equivalent',null,'message','CAMADA ENV // SEM EQUIVALENTE ATUAL // CREDENCIAL AUSENTE DO ELENCO CONSCIENTE') end,'crossClue',case when a.phase>=3 or a.locked then cl end,'anchor',jsonb_build_object('crewId',a.crew_id,'anchorId',a.anchor_id,'phase',a.phase,'stability',a.stability,'progress',a.progress,'publicState',a.public_state,'publicLog',a.public_log,'helpTokens',a.help_tokens,'locked',a.locked,'joined',a.joined,'interference',inter,'revision',a.revision,'output',case when a.locked then outp end),'revision',s.revision);
end$$;

create or replace function public.pani_eco_master_status(p_pin text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pani_private as $$declare s pani_private.eco_session%rowtype;a jsonb;l jsonb;begin if not public.pani_master_valid(p_pin) then raise exception 'unauthorized';end if;perform pani_private.eco_tick_session();select * into s from pani_private.eco_session where session_id='W77-02';select coalesce(jsonb_agg(jsonb_build_object('crewId',crew_id,'anchorId',anchor_id,'phase',phase,'stability',stability,'progress',progress,'locked',locked,'joined',joined,'lastSeen',last_seen,'helpTokens',help_tokens,'publicState',public_state,'secretState',secret_state,'interference',interference,'revision',revision)order by array_position(pani_private.eco_active_crew(),crew_id)),'[]') into a from pani_private.eco_anchor where session_id='W77-02';select coalesce(jsonb_agg(x order by(x->>'id')::bigint desc),'[]')into l from(select jsonb_build_object('id',id,'actor',actor,'type',event_type,'detail',detail,'createdAt',created_at)x from pani_private.eco_log where session_id='W77-02' order by id desc limit 80)q;return jsonb_build_object('released',s.released,'status',s.status,'paused',s.paused,'seedId',s.seed_id,'globalPressure',s.global_pressure,'presenceCharges',s.presence_charges,'ruptureAvailable',s.rupture_available,'coherence',s.coherence,'convergence',s.convergence,'secretState',s.secret_state,'anchors',a,'logs',l,'revision',s.revision);end$$;

create or replace function public.pani_eco_master_action(p_pin text,p_action text,p_payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pani_private as $$declare s pani_private.eco_session%rowtype;c text;t text;nodes jsonb;types jsonb:='[]';i int;e text;pa interval;u timestamptz;begin
 if not public.pani_master_valid(p_pin) then raise exception 'unauthorized';end if;select * into s from pani_private.eco_session where session_id='W77-02' for update;
 if p_action='start' then perform pani_private.eco_reset(coalesce((p_payload->>'seed')::int,1),true);
 elsif p_action='reset' then perform pani_private.eco_reset(coalesce((p_payload->>'seed')::int,s.seed_id),false);
 elsif p_action='stop' then update pani_private.eco_session set released=false,status='dormant',paused=false,paused_at=null,revision=revision+1 where session_id='W77-02';
 elsif p_action='pause' then if not s.paused then update pani_private.eco_session set paused=true,paused_at=now(),revision=revision+1 where session_id='W77-02';end if;
 elsif p_action='resume' then if s.paused then pa:=now()-s.paused_at;update pani_private.eco_session set paused=false,paused_at=null,convergence=case when nullif(convergence->>'windowEnd','') is not null then jsonb_set(convergence,'{windowEnd}',to_jsonb((convergence->>'windowEnd')::timestamptz+pa))when nullif(convergence->>'retryAt','') is not null then jsonb_set(convergence,'{retryAt}',to_jsonb((convergence->>'retryAt')::timestamptz+pa))else convergence end,revision=revision+1 where session_id='W77-02';update pani_private.eco_anchor set public_state=public_state||jsonb_build_object('buildDeadline',case when nullif(public_state->>'buildDeadline','')is not null then to_jsonb((public_state->>'buildDeadline')::timestamptz+pa)else public_state->'buildDeadline'end,'flowStartedAt',case when nullif(public_state->>'flowStartedAt','')is not null then to_jsonb((public_state->>'flowStartedAt')::timestamptz+pa)else public_state->'flowStartedAt'end,'flowCompleteAt',case when nullif(public_state->>'flowCompleteAt','')is not null then to_jsonb((public_state->>'flowCompleteAt')::timestamptz+pa)else public_state->'flowCompleteAt'end),revision=revision+1 where session_id='W77-02' and crew_id='eklay';end if;
 elsif p_action='configure_sec' then nodes:=p_payload->'nodes';if jsonb_typeof(nodes)<>'array' or jsonb_array_length(nodes)<>6 then raise exception 'route_requires_six_nodes';end if;for i in 0..4 loop e:=pani_private.eco_edge(nodes->>i,nodes->>(i+1));if e is null then raise exception 'invalid_route_edge';end if;types:=types||to_jsonb(e);end loop;update pani_private.eco_session set secret_state=secret_state||jsonb_build_object('secRoute',nodes,'secMoveTypes',types),revision=revision+1 where session_id='W77-02';update pani_private.eco_anchor set secret_state=jsonb_set(jsonb_set(secret_state,'{route}',nodes),'{moveTypes}',types),revision=revision+1 where session_id='W77-02' and crew_id='christian' and phase in(2,3) and not locked;
 elsif p_action in('grant_help','reduce_phase') then c:=p_payload->>'crewId';if not(c=any(pani_private.eco_active_crew()))then raise exception 'invalid_anchor';end if;update pani_private.eco_anchor set help_tokens=help_tokens+case when p_action='grant_help'then 1 else 2 end,stability=3,public_state=public_state||jsonb_build_object('serverAck','AUXÍLIO DO MESTRE REGISTRADO'),revision=revision+1 where session_id='W77-02' and crew_id=c and not locked;
 elsif p_action='interfere' then if s.paused or not s.released or s.status<>'active' then raise exception 'interference_unavailable';end if;if s.presence_charges<=0 then raise exception 'presence_depleted';end if;if exists(select 1 from pani_private.eco_anchor where session_id='W77-02' and phase=1 and not locked)then raise exception 'presence_locked_until_phase_two';end if;c:=p_payload->>'crewId';t:=p_payload->>'type';if not((c='gilbert'and t in('visual_mutation','verifier_echo','no_label'))or(c='eklay'and t in('remote_rotate','blind_queue','phantom_target'))or(c='christian'and t in('salto','false_echo','blind_camera'))or(c='willy'and t in('ectopic','label_swap','latency'))or(c='aliya'and t in('mirror_document','redaction','phantom_relation')))then raise exception 'invalid_interference';end if;u:=now()+case when t in('label_swap','salto')then interval '5 seconds'else interval '8 seconds'end;update pani_private.eco_anchor set interference=jsonb_build_object('type',t,'until',u,'ack','INTERFERÊNCIA ECO REGISTRADA'),secret_state=case when c='christian'and t='false_echo'then secret_state||'{"falseEcho":true}'when c='christian'and t='blind_camera'then secret_state||'{"blindCamera":true}'else secret_state end,revision=revision+1 where session_id='W77-02' and crew_id=c and not locked;update pani_private.eco_session set presence_charges=presence_charges-1,revision=revision+1 where session_id='W77-02';
 elsif p_action='rupture' then if s.status<>'convergence'or s.convergence->>'state'<>'open'or not s.rupture_available then raise exception 'rupture_unavailable';end if;c:=p_payload->>'crewId';if not(c=any(pani_private.eco_active_crew()))then raise exception 'invalid_anchor';end if;update pani_private.eco_anchor set interference=jsonb_build_object('type','rupture','until',now()+interval '5 seconds'),revision=revision+1 where session_id='W77-02' and crew_id=c;update pani_private.eco_session set rupture_available=false,revision=revision+1 where session_id='W77-02';
 else raise exception 'unknown_eco_master_action';end if;perform pani_private.eco_log_write('MASTER',p_action,c);return public.pani_eco_master_status(p_pin);
end$$;

create or replace function public.pani_eco_input(p_token text,p_action text,p_payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pani_private as $$
declare c text;s pani_private.eco_session%rowtype;a pani_private.eco_anchor%rowtype;st jsonb;sec jsonb;g jsonb;fb jsonb;hist jsonb;ok boolean:=false;i int;n int;idx int;cell text;piece text;route jsonb;cur text;nxt text;res text;found int:=0;mv text;pairs jsonb;exp jsonb;tested jsonb;ready jsonb;startt timestamptz;finish timestamptz;diff numeric;roundn int;
begin c:=pani_private.eco_auth_crew(p_token);if not(c=any(pani_private.eco_active_crew()))then raise exception 'anchor_not_assigned';end if;perform pani_private.eco_tick_anchor(c);perform pani_private.eco_tick_session();select * into s from pani_private.eco_session where session_id='W77-02' for update;select * into a from pani_private.eco_anchor where session_id='W77-02' and crew_id=c for update;if not s.released then raise exception 'eco_not_released';end if;if s.paused then raise exception 'eco_paused';end if;
 if p_action='convergence' then if not a.locked or s.status<>'convergence'or s.convergence->>'state'<>'open'then raise exception 'convergence_unavailable';end if;if now()>(s.convergence->>'windowEnd')::timestamptz then perform pani_private.eco_tick_session();raise exception 'convergence_window_closed';end if;ok:=case c when 'gilbert'then p_payload->>'marker'='NØ'and coalesce((p_payload->>'holdMs')::int,0)>=3000 when 'eklay'then pani_private.eco_same(p_payload->'nodes','["A","B","C"]')when 'christian'then p_payload->>'sector'='Ø-C'when 'willy'then pani_private.eco_same(p_payload->'sequence','["pulse","resp","neural","tonus"]')when 'aliya'then coalesce((p_payload->>'noName')::boolean,false)end;if not ok then raise exception 'invalid_convergence_action';end if;ready:=coalesce(s.convergence->'ready','[]');if not ready?c then ready:=ready||jsonb_build_array(c);end if;n:=jsonb_array_length(ready);if n=5 then update pani_private.eco_session set status='complete',convergence=convergence||jsonb_build_object('state','success','ready',ready,'readyCount',5,'completedAt',now()),revision=revision+1 where session_id='W77-02';else update pani_private.eco_session set convergence=convergence||jsonb_build_object('ready',ready,'readyCount',n),revision=revision+1 where session_id='W77-02';end if;return public.pani_eco_status(p_token);end if;
 if s.status<>'active'then raise exception 'eco_inputs_closed';end if;if a.locked then raise exception 'anchor_locked';end if;st:=a.public_state;sec:=a.secret_state;
 if p_action='use_help'then if a.help_tokens<=0 then raise exception 'no_help_tokens';end if;update pani_private.eco_anchor set help_tokens=help_tokens-1,public_state=public_state||jsonb_build_object('hint',pani_private.eco_hint(c,a.phase),'serverAck','AJUDA PANI REGISTRADA'),revision=revision+1 where session_id='W77-02'and crew_id=c;return public.pani_eco_status(p_token);end if;
 if c='gilbert'then
  if p_action='gen_test'and a.phase in(1,2,3)then g:=p_payload->'guess';fb:=pani_private.eco_code_feedback(g,sec->'code');if a.phase=2 then fb:=fb||jsonb_build_object('verifiers',jsonb_build_object('ORIGEM',case when g->>0=sec->'code'->>0 or g->>1=sec->'code'->>1 then 'PASS'else'FAIL'end,'COMPATIBILIDADE',case when (fb->>'exact')::int+(fb->>'present')::int>=3 then'PASS'else'FAIL'end,'CONTENÇÃO',case when g->>3=sec->'code'->>3 then'PASS'else'FAIL'end));elsif a.phase=3 then fb:=fb||'{"verifiers":{"ORIGEM":"PASS","COMPATIBILIDADE":"PASS","CONTENÇÃO":"PASS","DESCRIÇÃO":"FAIL"},"divergence":true}'::jsonb;end if;hist:=coalesce(st->'history','[]')||jsonb_build_array(jsonb_build_object('guess',g,'feedback',fb,'at',now()));update pani_private.eco_anchor set public_state=public_state||jsonb_build_object('history',hist,'lastFeedback',fb,'tests',case when phase=3 then coalesce((public_state->>'tests')::int,0)+1 else 0 end,'feedback','Tentativa processada pelo servidor.','serverAck','REGISTRADO'),revision=revision+1 where session_id='W77-02'and crew_id=c;if(fb->>'exact')::int=jsonb_array_length(sec->'code')and a.phase in(1,2)then perform pani_private.eco_advance(c);elsif a.phase in(1,2)and jsonb_array_length(hist)>=coalesce((st->>'maxAttempts')::int,8)then perform pani_private.eco_fail(c,'LIMITE DE TENTATIVAS // fase recalibrada.');end if;
  elsif p_action='gen_suspect'and a.phase=3 then if coalesce((st->>'tests')::int,0)<3 then raise exception 'three_tests_required';end if;if upper(p_payload->>'verifier')='DESCRIÇÃO'then perform pani_private.eco_advance(c);else perform pani_private.eco_fail(c,'VERIFICADOR INCORRETO');end if;
  elsif p_action='gen_fix'and a.phase=4 then fb:=pani_private.eco_code_feedback(p_payload->'support',sec->'code');if(fb->>'exact')::int=jsonb_array_length(sec->'code')and coalesce((p_payload->>'separateDescription')::boolean,false)then perform pani_private.eco_advance(c,'SUPORTE PRESERVADO // DESCRIÇÃO INCONSISTENTE');else perform pani_private.eco_fail(c,'FIXAÇÃO INCONSISTENTE');end if;else raise exception 'invalid_gen_action';end if;
 elsif c='eklay'then
  if p_action='ops_place'and a.phase in(1,2,3)then cell:=p_payload->>'cell';idx:=coalesce((st->>'queueIndex')::int,0);if cell is null or cell!~'^[0-9]+,[0-9]+$'or(st->'placed')?cell then raise exception 'invalid_cell';end if;if cell=st->>'origin'then raise exception 'reserved_cell';end if;if idx>=jsonb_array_length(st->'queue')then raise exception 'queue_empty';end if;piece:=st->'queue'->>idx;st:=jsonb_set(st,array['placed',cell],jsonb_build_object('piece',piece,'rot',0,'crossed',false),true);st:=jsonb_set(st,'{queueIndex}',to_jsonb(idx+1));if a.phase in(2,3)and nullif(st->>'buildDeadline','')is null then st:=jsonb_set(st,'{buildDeadline}',to_jsonb(now()+interval'12 seconds'));end if;update pani_private.eco_anchor set public_state=st||'{"feedback":"Peça posicionada.","serverAck":"REGISTRADO"}',revision=revision+1 where session_id='W77-02'and crew_id=c;
  elsif p_action='ops_rotate'and a.phase in(1,2,3)then cell:=p_payload->>'cell';if not(st->'placed')?cell then raise exception 'piece_locked';end if;st:=jsonb_set(st,array['placed',cell,'rot'],to_jsonb((coalesce((st#>>array['placed',cell,'rot'])::int,0)+1)%4));update pani_private.eco_anchor set public_state=st||'{"serverAck":"REGISTRADO"}',revision=revision+1 where session_id='W77-02'and crew_id=c;
  elsif p_action='ops_hold'and a.phase in(1,2,3)then cell:=p_payload->>'cell';if not(st->'placed')?cell then raise exception 'piece_missing';end if;if jsonb_array_length(coalesce(st->'anchors','[]'))>=1 and not(st->'anchors')?cell then raise exception 'anchor_charge_spent';end if;update pani_private.eco_anchor set public_state=jsonb_set(public_state,'{anchors}',case when(public_state->'anchors')?cell then public_state->'anchors'else(public_state->'anchors')||jsonb_build_array(cell)end)||'{"serverAck":"SEGURAR REGISTRADO"}',revision=revision+1 where session_id='W77-02'and crew_id=c;
  elsif p_action='ops_validate'and a.phase in(1,2,3)then ok:=pani_private.eco_ops_valid(st->'placed',sec->'solution');if not ok then perform pani_private.eco_fail(c,'ROTA INCOMPLETA');elsif a.phase=1 then perform pani_private.eco_advance(c);else startt:=coalesce((st->>'buildDeadline')::timestamptz,now());if startt<now()then startt:=now();end if;finish:=startt+make_interval(secs=>(st->>'pathLength')::int*1.3);update pani_private.eco_anchor set public_state=public_state||jsonb_build_object('routeValid',true,'flowStartedAt',startt,'flowCompleteAt',finish,'targetShifted',phase=3,'feedback','ROTA VALIDADA // PULSO EM TRÂNSITO','serverAck','REGISTRADO'),revision=revision+1 where session_id='W77-02'and crew_id=c;end if;
  elsif p_action='ops_node'and a.phase=4 then idx:=coalesce((st->>'nodeIndex')::int,0);if p_payload->>'node'=sec->'nodes'->>idx then idx:=idx+1;if idx=3 then perform pani_private.eco_advance(c,'ROTA VALIDADA // DESTINO SEM POSIÇÃO CONVENCIONAL');else update pani_private.eco_anchor set public_state=public_state||jsonb_build_object('nodeIndex',idx,'serverAck','REGISTRADO'),revision=revision+1 where session_id='W77-02'and crew_id=c;end if;else perform pani_private.eco_fail(c,'ORDEM DE NODE INCORRETA');end if;else raise exception 'invalid_ops_action';end if;
 elsif c='christian'then route:=sec->'route';idx:=coalesce((sec->>'routeIndex')::int,coalesce((st->>'routeIndex')::int,0));cur:=route->>least(idx,jsonb_array_length(route)-1);
  if p_action='sec_scan'and a.phase=1 then res:=case when p_payload->>'sector'=cur then'PRESENÇA'when p_payload->>'sector'='HUB'then'ECO RECENTE'else'AUSÊNCIA'end;update pani_private.eco_anchor set public_state=public_state||jsonb_build_object('round',coalesce((public_state->>'round')::int,0)+1,'lastScan',jsonb_build_object('sector',p_payload->>'sector','result',res),'feedback',res,'serverAck','SCAN REGISTRADO'),revision=revision+1 where session_id='W77-02'and crew_id=c;if res='PRESENÇA'then perform pani_private.eco_advance(c);end if;
  elsif a.phase=2 and p_action in('sec_scan','sec_crosscheck','sec_lockdown','sec_camera')then res:='AUSÊNCIA';if p_action='sec_scan'and p_payload->>'sector'=cur then res:='PRESENÇA';found:=1;elsif p_action='sec_lockdown'and p_payload->>'sector'=cur then res:='CONTATO RETIDO';found:=1;elsif p_action='sec_camera'and p_payload->>'sector'=cur then res:='CONTATO VISÍVEL';found:=1;end if;n:=jsonb_array_length(route);nxt:=case when idx<n-1 then route->>(idx+1)end;mv:=case when nxt is not null then pani_private.eco_edge(cur,nxt)end;st:=st||jsonb_build_object('routeIndex',least(idx+1,n-1),'findings',coalesce((st->>'findings')::int,0)+found,'scanLog',coalesce(st->'scanLog','[]')||jsonb_build_array(jsonb_build_object('action',p_action,'sector',p_payload->>'sector','result',res)),'moveLog',case when mv is null then coalesce(st->'moveLog','[]')else coalesce(st->'moveLog','[]')||jsonb_build_array(mv)end,'feedback',res,'serverAck','REGISTRADO');update pani_private.eco_anchor set public_state=st,secret_state=secret_state||jsonb_build_object('routeIndex',least(idx+1,n-1)),revision=revision+1 where session_id='W77-02'and crew_id=c;if idx>=n-2 then if(st->>'findings')::int>=1 then perform pani_private.eco_advance(c);else perform pani_private.eco_fail(c,'CONTATO PERDIDO');end if;end if;
  elsif a.phase=3 and p_action='sec_scan'then n:=jsonb_array_length(route);mv:=case when idx=coalesce((sec->>'jumpIndex')::int,2)then'?'when idx<n-1 then pani_private.eco_edge(cur,route->>(idx+1))end;st:=st||jsonb_build_object('routeIndex',least(idx+1,n-1),'moveLog',coalesce(st->'moveLog','[]')||case when mv is null then'[]'::jsonb else jsonb_build_array(mv)end,'serverAck','REGISTRADO');update pani_private.eco_anchor set public_state=st,secret_state=secret_state||jsonb_build_object('routeIndex',least(idx+1,n-1)),revision=revision+1 where session_id='W77-02'and crew_id=c;
  elsif a.phase=3 and p_action='sec_accuse_jump'then if coalesce((st->>'routeIndex')::int,0)<3 then raise exception'insufficient_tracking';end if;if(p_payload->>'index')::int=coalesce((sec->>'jumpIndex')::int,2)then perform pani_private.eco_advance(c);else perform pani_private.eco_fail(c,'SALTO MARCADO INCORRETAMENTE');end if;
  elsif a.phase=4 and p_action='sec_blackbox'then if(p_payload->>'index')::int=(sec->>'firstImpossible')::int then perform pani_private.eco_advance(c,'PRESENÇA INTERNA CONFIRMADA');else perform pani_private.eco_fail(c,'PONTO IMPOSSÍVEL INCORRETO');end if;else raise exception'invalid_sec_action';end if;
 elsif c='willy'then
  if p_action='med_repeat'and a.phase=1 then g:=p_payload->'sequence';if pani_private.eco_same(g,st->'sequence')then n:=(st->>'length')::int;if n>=7 then perform pani_private.eco_advance(c);else select jsonb_agg(value order by ord)into g from jsonb_array_elements(sec->'fullSequence')with ordinality x(value,ord)where ord<=n+1;update pani_private.eco_anchor set public_state=public_state||jsonb_build_object('sequence',g,'length',n+1,'serverAck','REGISTRADO'),revision=revision+1 where session_id='W77-02'and crew_id=c;end if;else perform pani_private.eco_fail(c,'ORDEM FISIOLÓGICA INCORRETA');end if;
  elsif p_action='med_timed'and a.phase=2 then g:=p_payload->'sequence';exp:=sec->'sequence';ok:=jsonb_typeof(g)='array'and jsonb_array_length(g)=jsonb_array_length(exp);if ok then for i in 0..jsonb_array_length(exp)-1 loop if g->i->>'channel'<>exp->i->>'channel'or abs((g->i->>'time')::numeric-(exp->i->>'time')::numeric)>450 then ok:=false;end if;end loop;end if;if ok then roundn:=coalesce((st->>'round')::int,0)+1;if roundn>=2 then perform pani_private.eco_advance(c);else update pani_private.eco_anchor set public_state=public_state||jsonb_build_object('round',roundn,'serverAck','REGISTRADO'),revision=revision+1 where session_id='W77-02'and crew_id=c;end if;else perform pani_private.eco_fail(c,'DEFASAGEM FORA DA JANELA');end if;
  elsif p_action='med_markers'and a.phase=3 then g:=p_payload->'markers';exp:=sec->'starts';ok:=jsonb_typeof(g)='array'and jsonb_array_length(g)=6;if ok then for i in 0..5 loop if abs((g->>i)::numeric-(exp->>i)::numeric)>8 then ok:=false;end if;end loop;end if;if ok and p_payload->>'conclusion'=sec->>'conclusion'then perform pani_private.eco_advance(c);else perform pani_private.eco_fail(c,'RELAÇÃO TEMPORAL INCONSISTENTE');end if;
  elsif p_action='med_preserve'and a.phase=4 then if pani_private.eco_same(p_payload->'sequence',sec->'rawSequence')and coalesce((p_payload->>'preserveRaw')::boolean,false)then perform pani_private.eco_advance(c,'RESPOSTA COLETIVA // ANTECEDE REGISTRO AMBIENTAL');else perform pani_private.eco_fail(c,'REGISTRO BRUTO CONTAMINADO');end if;else raise exception'invalid_med_action';end if;
 elsif c='aliya'then
  if p_action='inv_classify'and a.phase=1 then if p_payload->'assignments'=sec->'assignments'then perform pani_private.eco_advance(c);else perform pani_private.eco_fail(c,'CLASSIFICAÇÃO INCONSISTENTE');end if;
  elsif p_action='inv_pairs'and a.phase=2 then pairs:=p_payload->'pairs';exp:=sec->'pairs';ok:=jsonb_typeof(pairs)='array'and jsonb_array_length(pairs)=4;if ok then select not exists(select 1 from jsonb_array_elements(exp)e(value) where not exists(select 1 from jsonb_array_elements(pairs)z(value) where z.value@>e.value and e.value@>z.value))into ok;end if;if ok then perform pani_private.eco_advance(c);else perform pani_private.eco_fail(c,'PARES INCOMPLETOS');end if;
  elsif p_action='inv_hypothesis'and a.phase=3 then cell:=p_payload->>'hypothesis';res:=sec->'results'->>cell;if res is null then raise exception'invalid_hypothesis';end if;tested:=coalesce(st->'tested','{}')||jsonb_build_object(cell,res);update pani_private.eco_anchor set public_state=public_state||jsonb_build_object('tested',tested,'lastResult',res,'serverAck','REGISTRADO'),revision=revision+1 where session_id='W77-02'and crew_id=c;if tested?'five'and tested?'pani'and tested?'one'then perform pani_private.eco_advance(c);end if;
  elsif p_action='inv_fix'and a.phase=4 then g:=p_payload->'outputs';ok:=jsonb_typeof(g)='array'and jsonb_array_length(g)=5 and g@>(sec->'outputs')and(sec->'outputs')@>g and coalesce((p_payload->>'noName')::boolean,false);if ok then perform pani_private.eco_advance(c,'CINCO SUPORTES // UMA ESTRUTURA RECORRENTE // SEM NOME');else perform pani_private.eco_fail(c,'RELAÇÃO NOMEADA OU INCOMPLETA');end if;else raise exception'invalid_inv_action';end if;
 end if;return public.pani_eco_status(p_token);
end$$;

select pani_private.eco_reset(1,false);

revoke all on function public.pani_eco_status(text),public.pani_eco_input(text,text,jsonb),public.pani_eco_master_status(text),public.pani_eco_master_action(text,text,jsonb) from public,anon,authenticated;
